def dump(ids):
    n=0
    for cid in ids:
        pred,body,conf=P[cid]
        rec={"case_id":cid,"prediction_text":pred,"basis":"liuyao\n"+body,"confidence":conf,"trigger":TRIG.get(cid,{"changed_main":False,"reserve_used":False,"disputed":False,"reason":""})}
        with open(os.path.join(BASE,cid+".json"),"w",encoding="utf-8") as f: json.dump(rec,f,ensure_ascii=False,indent=1)
        n+=1
    return n
